let cloudStatus={configured:false,user:null,status:'initializing'}, remoteViewPending=false;
const NAV=[['home','◫','学习总览'],['writing','✧','教材闯关'],['listening','◎','听力原题'],['mistakes','↻','错题复习'],['library','▱','资料库'],['tools','⌘','辅助工具']];
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function persist(activity=false){if(activity)S.activity[TODAY()]=true;try{window.StudyCloud.save(S)}catch(error){toast('本地保存未完成，请先导出备份');storageOK=false}updateCloudHeader()}
function updateCloudHeader(){const st=cloudStatus;const label=st.message||(st.user?'正在同步…':'游客模式 · 本机保存');$('#save-state').textContent=label;$('#save-state').dataset.state=st.status||'guest';$('#account-label').textContent=st.user?(S.settings.name||st.user.email?.split('@')[0]||'我的账号'):st.authProvider==='github'?'GitHub 登录':'登录 / 注册';$('#account-button').classList.toggle('signed-in',!!st.user);const level=learningLevel();$('#sidebar-level').textContent=`LV. ${String(level.level).padStart(2,'0')} · ${level.title}`}
function learningLevel(){const xp=Object.entries(S.tasks).reduce((n,[k,v])=>n+(v?(k.startsWith('learn:')?10:k.startsWith('book:')?60:30):0),0)+Object.values(S.words).filter(w=>w.known).length*4+Object.values(S.read).filter(Boolean).length*50+Object.entries(S.results).filter(([k])=>k.startsWith('unit-')).reduce((n,[,r])=>n+Math.max(0,r.score)*10,0)+Object.values(S.mock).filter(m=>m.submitted).length*100;const level=Math.floor(xp/300)+1;return{xp,level,progress:xp%300,title:['初航者','探索者','追光者','跃迁者','领航者'][Math.min(4,Math.floor((level-1)/3))]}}
function reward(){window.StudyFX?.celebrate();updateCloudHeader()}
function account(){window.AccountUI.render($('#main'),{heading,toast})}
function onCloudStatus(st){cloudStatus=st;window.AccountUI?.onStatus(st);updateCloudHeader();if(st.recovery&&location.hash!=='#account')navigate('account')}
function receiveCloudState(next,meta={}){if(!validState(next))return false;const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);const playing=$$('audio').some(a=>!a.paused)||window.speechSynthesis?.speaking;if(!meta.forceRender&&(meta.reason==='sync'||meta.reason==='conflict')&&(editing||playing)){remoteViewPending=true;$('#sync-notice').classList.remove('hidden');return false}S=next;wordDeck=[];wordIndex=0;remoteViewPending=false;$('#sync-notice').classList.add('hidden');if(D.units.length)render();updateCloudHeader();return true}
