window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
const PLAN14=[['找回语感',['听力 Unit 1：先盲听，再订正','Sentence skills：句子完整与边界','词汇起步：认识 20 个核心词']],['句子的骨架',['听力 Unit 2：抓住词组边界','Sentence skills：并列与从属','复习昨日生词 + 20 个新词']],['从句到段落',['听力 Unit 3：新闻长短语','Paragraph structure：主题句','复习错词 + 20 个新词']],['让句子连起来',['听力 Unit 4：抓关键词','Unity and coherence：统一与连贯','复习错词 + 20 个新词']],['把观点写具体',['听力 Unit 5：听清细节','Supporting details：例证与事实','复习错词 + 20 个新词']],['从段落到文章',['听力 Unit 6：回听易错句','From paragraph to essay：文章结构','复习错词 + 20 个新词']],['第一轮复盘',['听力 Unit 1–6：重做错空','用主题句写一个完整段落','复习本周易错词']],['因果关系',['听力 Unit 7：长句意群','Cause and effect essays：原因与结果','复习错词 + 20 个新词']],['观点与反驳',['听力 Unit 8：完整自测','Argumentative essays：观点与反驳','复习错词 + 20 个新词']],['改写而不改意',['听力 Unit 3、5：复习错空','Paraphrase：换句式，保留原意','复习错词 + 20 个新词']],['抓住文章主旨',['听力 Unit 7、8：复习错空','Summary 与 RA：主旨和学术结构','复习全部标记生词']],['模拟卷 A',['完整完成模拟卷 A','对照评分要点，自评主观题','复盘错题，补齐薄弱项']],['查漏补缺',['听力 Unit 1–8：错空回听','复习写作模板与典型语法错误','易错词快速抽查']],['模拟卷 B',['完整完成模拟卷 B','对照评分要点，自评主观题','回顾错题本与最终复习清单']]];
const PLAN7=[['恢复句子与听感',['听力 Unit 1–2：盲听后订正','Sentence skills：完整句与纠错','词汇集中复习 40 个']],['段落基础',['听力 Unit 3–4：词组填空','Paragraph structure + Unity and coherence','词汇集中复习 40 个']],['写出完整文章',['听力 Unit 5–6：精听跟读','Supporting details + From paragraph to essay','词汇集中复习 40 个']],['组织论证',['听力 Unit 7–8：完整自测','Cause and effect + Argumentative essays','词汇集中复习 40 个']],['改写与摘要',['回听所有错空','Paraphrase、Summary 与 RA 概览','复习高频短语与易错词']],['模拟卷 A',['完成模拟卷 A 并订正','查漏：句子、段落、摘要','复习错题本']],['模拟卷 B',['完成模拟卷 B 并订正','回顾作文模板和评分要点','轻量回听，整理最终清单']]];
function planData(){return S.plan===7?PLAN7:PLAN14}
function taskGo(i){return S.day>=(S.plan===7?6:12)&&i===0?'mocks':i===0?'listening':i===1?'writing':'vocabulary'}
function journeyContext(){return{state:S,data:D,level:learningLevel(),openCourse:id=>{lessonId=id;navigate('writing');if(route==='writing')writing();window.scrollTo(0,0)}}}
function home(){window.StudyJourney.home($('#main'),journeyContext())}
function normalize(v){return String(v||'').normalize('NFKC').toLowerCase().replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/(?<!\d)\.|\.(?!\d)/g,'').replace(/[,!?;:，。！？；：]/g,'').replace(/\s+/g,' ').trim()}
function accepted(value,q){return [q.answer,...(q.alternatives||[])].some(a=>normalize(a)===normalize(value))}
function currentUnit(){return D.units.find(u=>+u.id===+unitId)||D.units[0]}
function listening(){const u=currentUnit();if(!u){$('#main').innerHTML=heading('LISTEN & NOTICE','听力训练','暂未加载听力资料。');return}unitId=u.id;if(!window.ListeningFlow.shouldPractice(S,u)){window.ListeningFlow.guide($('#main'),{state:S,unit:u,units:D.units,onStart:()=>{persist();listening()},onUnit:id=>{unitId=id;listening()}});return}if(+u.id===1)u.notes='第 6 空的原答案存在疑似录入问题，提交后请结合原音与《资料听力核查》核验。';if(+u.id===5)u.notes='第 8 空的原答案存在疑似录入问题，提交后请结合原音与《资料听力核查》核验。';const questions=u.passages.flatMap(p=>p.questions),draft=S.drafts[`unit-${u.id}`]||{},res=S.results[`unit-${u.id}`];$('#main').innerHTML=heading('LISTEN & NOTICE','把听到的，准确写下来。','先盲听填空 → 提交核对 → 精听跟读。支持调速、回退和片段循环。')+`<div class="split"><div class="unit-list">${D.units.map(x=>`<button class="unit-button ${x.id===u.id?'active':''}" data-unit="${x.id}"><span class="unit-number">${String(x.id).padStart(2,'0')}</span><span><strong>Unit ${x.id}</strong><small>${x.passages.reduce((n,p)=>n+p.questions.length,0)} 空 · ${S.results[`unit-${x.id}`]?`${S.results[`unit-${x.id}`].score} 已答对`:'尚未提交'}</small></span></button>`).join('')}</div><div><div class="audio-panel"><div class="row-between"><h3>${esc(u.title||'Unit '+u.id+' · 新闻听力')}</h3><span class="tag">课程原始音频</span></div>${(u.audio||[]).map((a,i)=>`<div class="audio-row-label">${u.audio.length>1?esc(a.label):''}</div><audio id="audio-${i}" controls preload="metadata" src="${esc(a.path)}">你的浏览器不支持音频播放。</audio><a class="quiet" href="${esc(a.path)}" download>下载本单元原音 ↓</a>`).join('')}<div class="audio-controls"><button class="secondary small" id="rewind">↶ 退 5 秒</button><label class="hint">语速 <select id="speed" aria-label="播放速度">${[.65,.8,1,1.2].map(n=>`<option value="${n}" ${n===1?'selected':''}>${n}×</option>`).join('')}</select></label><button class="secondary small" id="loop-a">设置 A 点</button><button class="secondary small" id="loop-b">设置 B 点</button><button class="quiet" id="loop-clear">取消循环</button><span id="loop-info" class="range-tip"></span></div></div>${u.notes?`<div class="notice">${esc(Array.isArray(u.notes)?u.notes.join('；'):u.notes)}</div>`:''}<div class="panel"><div class="section-head"><h2>听新闻，补全原词原短语</h2><span class="progress-text">${questions.length} 个空</span></div><p class="hint">按录音填写完整内容，大小写、句末标点不影响自动核对。长短语可以先记下听清的部分。</p><div id="listen-score"></div>${u.passages.map((p,i)=>`<section class="listening-passage"><h3 class="space-top">${i+1}. ${esc(p.title||'News report')}</h3><div class="passage">${p.parts.map(part=>part.blank!=null?`<span class="blank-wrap"><label for="blank-${esc(part.blank)}">${esc(p.questions.find(q=>q.id===part.blank)?.number||part.blank)}</label><input autocomplete="off" spellcheck="false" class="blank-input" id="blank-${esc(part.blank)}" data-blank="${esc(part.blank)}" aria-label="第 ${esc(p.questions.find(q=>q.id===part.blank)?.number||part.blank)} 空" value="${esc(draft[part.blank]||'')}"><span class="answer-feedback" data-feedback="${esc(part.blank)}"></span></span>`:esc(part.text)).join('')}</div></section>`).join('')}<div class="button-row"><button class="primary" id="submit-listening">提交并核对答案</button><button class="secondary" id="retry-listening">重新自测</button><button class="quiet" id="show-listening-method">练习方法 ↗</button></div><p class="source-detail">来源：课程 Unit ${u.id} 题目与答案文档 · 答案仅在提交后展示。</p></div></div></div>`;$$('[data-unit]').forEach(x=>x.onclick=()=>{unitId=+x.dataset.unit;loopStart=loopEnd=null;$$('audio').forEach(a=>a.pause());listening()});$$('[data-blank]').forEach(x=>x.oninput=()=>{S.drafts[`unit-${u.id}`]??={};S.drafts[`unit-${u.id}`][x.dataset.blank]=x.value;x.classList.remove('correct','incorrect');const feedback=$$('[data-feedback]').find(f=>f.dataset.feedback===x.dataset.blank);if(feedback)feedback.textContent='';if($('#listen-score').textContent)$('#listen-score').innerHTML='<p class="hint">答案已修改，请重新提交核对。本次成绩尚未更新。</p>';persist()});const activeAudio=()=>$$('audio').find(a=>!a.paused)||$('audio');$('#speed').onchange=e=>$$('audio').forEach(a=>a.playbackRate=+e.target.value);$('#rewind').onclick=()=>{const a=activeAudio();if(a)a.currentTime=Math.max(0,a.currentTime-5)};$('#loop-a').onclick=()=>{loopStart=activeAudio()?.currentTime??0;loopEnd=null;$('#loop-info').textContent=`A: ${loopStart.toFixed(1)}s`};$('#loop-b').onclick=()=>{const b=activeAudio()?.currentTime??0;if(loopStart===null||b<=loopStart+.5){toast('请先设 A 点，再播放到至少 0.5 秒后的 B 点');return}loopEnd=b;$('#loop-info').textContent=`循环 ${loopStart.toFixed(1)}–${loopEnd.toFixed(1)}s`};$('#loop-clear').onclick=()=>{loopStart=loopEnd=null;$('#loop-info').textContent=''};$$('audio').forEach(a=>{a.ontimeupdate=()=>{if(loopEnd!=null&&a.currentTime>=loopEnd)a.currentTime=loopStart};a.onplay=()=>$$('audio').forEach(other=>{if(other!==a)other.pause()})});$('#submit-listening').onclick=()=>{const part=window.ListeningFlow.position(S,u),current=u.passages[part].questions;if(!current.some(q=>document.getElementById('blank-'+q.id).value.trim())){toast('先尝试填写本篇至少一个空，再提交核对。');return}let score=0;current.forEach(q=>{const input=$$('[data-blank]').find(x=>x.dataset.blank===q.id),feedback=$$('[data-feedback]').find(x=>x.dataset.feedback===q.id);if(!input)return;const ok=accepted(input.value,q);if(ok)score++;input.classList.toggle('correct',ok);input.classList.toggle('incorrect',!ok);feedback.className=`answer-feedback ${ok?'good':''}`;feedback.textContent=ok?'✓ 正确':`${input.value.trim()?'参考答案':'未填写'}：${q.answer}${q.translation?' · '+q.translation:''}`;if(!ok)S.mistakes[q.id]={id:q.id,type:'listening',unit:u.id,prompt:`Unit ${u.id} · 第 ${q.number} 空`,answer:q.answer,yourAnswer:input.value,explanation:q.translation||'',date:TODAY()};else delete S.mistakes[q.id]});S.results[`listen-part-${u.id}-${part}`]={score,total:current.length,date:TODAY()};window.ListeningFlow.aggregate(S,u);persist(true);const step=$(`[data-listen-step="${part}"]`);if(step)step.classList.add('done');$('#listen-score').innerHTML=`<div class="score-banner"><strong>${score} / ${current.length}</strong>本篇逐空核对已完成。错空已收进错题本；未填也会显示答案。</div>`;reward();toast('挑战已完成，成绩已保存')};$('#retry-listening').onclick=()=>{const part=window.ListeningFlow.position(S,u);S.drafts[`unit-${u.id}`]??={};u.passages[part].questions.forEach(q=>delete S.drafts[`unit-${u.id}`][q.id]);delete S.results[`listen-part-${u.id}-${part}`];window.ListeningFlow.aggregate(S,u);persist();listening();toast('已清空本篇填写，其他新闻的作答已保留')};$('#show-listening-method').onclick=()=>openMatching('听力使用方法');window.ListeningFlow.mount($('#main'),{s:S,u,save:persist,toast,render:()=>{$$('audio').forEach(a=>a.pause());listening()}})}
function writing(){if(lessonId){lessonView();return}window.StudyJourney.catalog($('#main'),journeyContext())}
function freewriting(){$('#main').innerHTML=heading('OPTIONAL WRITING DESK','保留想写的每一句。','自由写作辅助工具；指定教材任务请在对应原题关卡完成。')+`<div class="panel space-top"><div class="section-head"><h2>写作练习桌</h2><span class="tag">自动保存草稿</span></div><p class="hint">可自行设定写作长度，150–200 词仅是原自编训练建议，并非已确认的期末要求。工作台提供字数统计和自查清单；详细批改可复制文章后将文章交给教师批改。</p><label for="essay-prompt" class="hint">本次练习题目</label><input id="essay-prompt" style="width:100%;margin:8px 0 12px" value="${esc(S.essays.prompt||'Should postgraduate students learn academic English?')}" aria-label="写作题目"><textarea id="essay-draft" rows="9" placeholder="Write your essay here…" aria-label="作文草稿">${esc(S.essays.draft||'')}</textarea><div class="status-row"><span id="essay-count">0 words</span><span>自定目标 · 不代表考试字数</span></div><div class="checklist">${['有明确观点和主题句','每段围绕一个核心意思','使用例子或原因支持观点','连接自然，结尾回扣主题','核对主谓、时态、标点和拼写'].map((t,i)=>`<label><input type="checkbox" data-essaycheck="${i}" ${S.essays.checks?.[i]?'checked':''}>${t}</label>`).join('')}</div><div class="button-row"><button class="primary" id="copy-essay">复制作文</button><button class="secondary" id="download-essay">下载草稿</button><button class="quiet" id="open-template">作文模板与句型 →</button></div></div>`;$$('[data-lesson]').forEach(b=>b.onclick=()=>{lessonId=b.dataset.lesson;writing();window.scrollTo(0,0)});const count=()=>{$('#essay-count').textContent=wordCount($('#essay-draft').value)+' words'};count();$('#essay-draft').oninput=()=>{S.essays.draft=$('#essay-draft').value;persist();count()};$('#essay-prompt').oninput=()=>{S.essays.prompt=$('#essay-prompt').value;persist()};$$('[data-essaycheck]').forEach(c=>c.onchange=()=>{S.essays.checks??={};S.essays.checks[c.dataset.essaycheck]=c.checked;persist(true)});$('#copy-essay').onclick=()=>copy(`写作批改\n题目：${S.essays.prompt||$('#essay-prompt').value}\n请根据课程材料检查结构、逻辑、语法与表达，并给出修改理由。\n\n${S.essays.draft||''}`);$('#download-essay').onclick=()=>download('我的英语作文.txt',`${$('#essay-prompt').value}\n\n${S.essays.draft||''}`,'text/plain');$('#open-template').onclick=()=>openMatching('05_作文模板')}
let reviewMission=null;
function lessonView(){const l=D.lessons.find(x=>x.id===lessonId);if(!l){lessonId='';writing();return}const course=D.courses.find(c=>c.id===l.id);const chapter=window.StudyChapters.render($('#main'),{lesson:l,course,state:S,save:persist,reward,toast,onBack:()=>{lessonId='';writing()},onSupplement:()=>readFile(l.markdownPath,l.title+' · 教材讲解与自编拓展')});if(reviewMission?.courseId===l.id){const index=course?.missions.findIndex(m=>m.id===reviewMission.missionId);reviewMission=null;if(index>=0)chapter.showMission(index)}}
function bookReviews(){return D.courses.flatMap(course=>course.missions.filter(m=>S.results['book:'+course.id+':'+m.id]?.reviewNeed).map(m=>({course,mission:m,result:S.results['book:'+course.id+':'+m.id]})))}
function tools(){window.StudyJourney.tools($('#main'))}
function mockKey(q){return [...String(q.answer).matchAll(/(?:^|\n)(\d+)\.\s*([^\n]+)/g)].map(m=>({number:m[1],answer:m[2]}))}
function mockListeningInputs(q,m){return esc(q.prompt).replace(/\[(\d+)\]\s*_+/g,(_,n)=>`<span class="blank-wrap"><label for="mockq-${esc(q.id)}-${n}">${n}</label><input class="blank-input" id="mockq-${esc(q.id)}-${n}" data-mockanswer="${esc(q.id)}--${n}" autocomplete="off" spellcheck="false" value="${esc(m.answers[q.id+'--'+n]||'')}" aria-label="模拟听力第 ${n} 空"></span>`)}
function mockListeningScore(q,m){const keys=mockKey(q),score=keys.filter(k=>normalize(m.answers[q.id+'--'+k.number])===normalize(k.answer)).length;return `听力核对：${score} / ${keys.length} 空正确`}
function mockListeningAnswers(q,m){return mockKey(q).map(k=>`${k.number}. ${m.answers[q.id+'--'+k.number]||'未填写'}`).join('\n')}
const wordCount=t=>(t.match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g)||[]).length;
function startDeck(mode='all'){const today=TODAY();let words=D.words.filter(w=>mode==='all'||mode==='new'&&!S.words[w.id]?.known||mode==='due'&&S.words[w.id]&&(!S.words[w.id].known||S.words[w.id].next<=today));if(!words.length){toast('这个筛选下没有待复习词汇，先开始一组新词');words=D.words.filter(w=>!S.words[w.id]?.known)};wordDeck=[...words].sort(()=>Math.random()-.5).slice(0,20);wordIndex=0;flipped=false;vocabulary()}
function vocabulary(){if(!wordDeck.length&&D.words.length)wordDeck=[...D.words].filter(w=>!S.words[w.id]?.known).slice(0,20);const w=wordDeck[wordIndex];$('#main').innerHTML=heading('WORDS THAT STAY','让陌生，慢慢变熟悉。','辅助词汇卡，不是已确认的独立考试项目。按需复习；备考主线请优先做教材原题。',`<span class="date-pill">${Object.values(S.words).filter(x=>x.known).length} / ${D.words.length} 已掌握</span>`)+`<div class="toolbar"><button class="secondary small" id="deck-all">随机 20 词</button><button class="secondary small" id="deck-new">未掌握词</button><button class="secondary small" id="deck-due">待复习词</button><div class="segmented"><button data-wordmode="en" class="${wordMode==='en'?'active':''}">英 → 中</button><button data-wordmode="zh" class="${wordMode==='zh'?'active':''}">中 → 英</button></div></div><div class="flash-layout"><div class="status-row"><span>${w?`第 ${wordIndex+1} / ${wordDeck.length} 个`:'本组已完成'}</span><span>${w?esc(w.theme||'学术词汇'):''}</span></div>${w?`<button class="flash-card" id="flash" aria-label="翻转单词卡"><span class="tag">${flipped?'参考释义':'点击卡片查看答案'}</span><div class="word">${esc(wordMode==='en'?w.english:w.chinese)}</div>${wordMode==='en'?`<div class="ipa">${esc(w.ipa)}</div>`:''}${flipped?`<div class="translation">${esc(wordMode==='en'?w.chinese:w.english)}</div>${wordMode==='zh'?`<div class="ipa">${esc(w.ipa)}</div>`:''}<div class="example-line">${esc(w.example)}</div><p class="source">来源：${esc(w.source)}</p>`:''}</button><div class="flash-buttons"><button class="secondary" id="word-again" ${!flipped?'disabled':''}>还不熟悉 · 再练</button><button class="primary" id="word-known" ${!flipped?'disabled':''}>记住了 ✓</button></div><div class="session-note">点击翻卡 · 自评掌握度 · 进度自动保存</div>`:`<div class="panel empty"><h3>这一组，完成了。</h3><p>短暂休息，再开始下一组。新掌握的词会在明天进入复习。</p><button class="primary" id="deck-next">开始下一组</button></div>`}</div><section class="panel space-top"><div class="section-head"><h2>全部词汇</h2><button class="quiet" id="download-vocab">下载 CSV ↗</button></div><div class="toolbar"><input class="search" id="vocab-search" placeholder="搜索单词、释义或来源…" aria-label="搜索词汇"><select id="vocab-theme" aria-label="按主题筛选"><option value="">全部主题</option>${[...new Set(D.words.map(w=>w.theme).filter(Boolean))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div class="table-scroll" id="word-results"></div></section>`;$('#deck-all').onclick=()=>startDeck();$('#deck-new').onclick=()=>startDeck('new');$('#deck-due').onclick=()=>startDeck('due');$$('[data-wordmode]').forEach(b=>b.onclick=()=>{wordMode=b.dataset.wordmode;flipped=false;vocabulary()});if(w){$('#flash').onclick=()=>{flipped=!flipped;vocabulary()};const mark=known=>{let streak=known?(S.words[w.id]?.streak||0)+1:0;let next=new Date();next.setDate(next.getDate()+(known?[1,3,7,14,30][Math.min(streak-1,4)]:0));S.words[w.id]={known,streak,next:next.toLocaleDateString('sv-SE'),date:TODAY()};persist(true);if(known)reward();wordIndex++;flipped=false;vocabulary()};$('#word-again').onclick=()=>mark(false);$('#word-known').onclick=()=>mark(true)}else if($('#deck-next'))$('#deck-next').onclick=()=>startDeck('new');$('#vocab-search').oninput=wordResults;$('#vocab-theme').onchange=wordResults;$('#download-vocab').onclick=()=>openMatching('03_词汇',true);wordResults()}
function wordResults(){const q=$('#vocab-search').value.toLowerCase().trim(),theme=$('#vocab-theme').value,items=D.words.filter(w=>(!theme||w.theme===theme)&&(!q||[w.english,w.chinese,w.source].some(v=>String(v||'').toLowerCase().includes(q))));$('#word-results').innerHTML=`<p class="hint">找到 ${items.length} 个词条${items.length>60?'，显示前 60 个，请搜索缩小范围':''}。</p><table class="word-table"><thead><tr><th>英文 / 音标</th><th>中文释义</th><th class="hide-mobile">例句与来源</th><th>掌握</th></tr></thead><tbody>${items.slice(0,60).map(w=>`<tr><td>${esc(w.english)}<small>${esc(w.ipa)}</small></td><td>${esc(w.chinese)}</td><td class="hide-mobile">${esc(w.example)}<small>${esc(w.source)}</small></td><td><input type="checkbox" data-known="${esc(w.id)}" aria-label="标记 ${esc(w.english)} 已掌握" ${S.words[w.id]?.known?'checked':''}></td></tr>`).join('')}</tbody></table>`;$$('[data-known]').forEach(c=>c.onchange=()=>{S.words[c.dataset.known]={...(S.words[c.dataset.known]||{}),known:c.checked,next:TODAY(),date:TODAY()};persist(true)})}
function mocks(){if(mockId){mockView();return}$('#main').innerHTML=heading('PRACTICE WITH PURPOSE','给自己一次完整的演练。','两套自编拓展练习，不是教材原题，也不是教师公布的试卷。请先完成教材原题。')+`<div class="notice">建议先完成一轮复习。听力为原创模拟新闻，可使用设备英文朗读；主观题请按参考答案和评分要点自评。</div><div class="two-grid">${D.papers.map(p=>`<section class="panel mock-card"><div class="mock-number">PRACTICE PAPER ${esc(p.id)}</div><h3>${esc(p.title)}</h3><span class="tag">建议 ${p.duration||100} 分钟</span><ul>${p.sections.map(s=>`<li>${esc(s.title)} · ${s.id==='listening'?10:s.questions.length} ${s.id==='listening'?'空':'题'}</li>`).join('')}</ul><p class="hint">${S.mock[p.id]?.submitted?'已交卷 · 可查看参考答案':S.mock[p.id]?.started?'存在已保存作答 · 可继续':'准备好后，开始计时。'}</p><button class="primary" data-mock="${esc(p.id)}">${S.mock[p.id]?.submitted?'查看作答与解析':S.mock[p.id]?.started?'继续作答':'进入模拟考场'} →</button></section>`).join('')}</div>`;$$('[data-mock]').forEach(b=>b.onclick=()=>{mockId=b.dataset.mock;mocks();window.scrollTo(0,0)})}
function mockView(){clearInterval(examInterval);const p=D.papers.find(p=>p.id===mockId);if(!p){mockId='';mocks();return}S.mock[p.id]??={answers:{},started:null,submitted:false};const m=S.mock[p.id];m.answers??={};$('#main').innerHTML=`<button class="link-back" id="mock-back">← 返回模拟考场</button>`+heading(`PRACTICE PAPER ${esc(p.id)}`,esc(p.title),'作答自动保存。计时为练习提示，超时后仍可补完并提交。')+`<div class="sticky-toolbar"><div><span class="timer" id="exam-timer">${p.duration||100}:00</span><span class="hint"> ${m.submitted?'已交卷':m.started?'计时中':'尚未开始'}</span></div><div class="button-row" style="margin:0">${!m.started?'<button class="primary" id="start-mock">开始计时</button>':''}<button class="${m.submitted?'secondary':'primary'}" id="submit-mock">${m.submitted?'重新练习此卷':'提交并查看参考'}</button></div></div>${(p.listeningScripts||[]).length?`<div class="audio-panel"><h3>原创新闻 · 设备朗读</h3><p class="hint">这是文字转语音练习，声音取决于设备。播放时隐藏听力稿；设备没有英文语音时，可请他人朗读，或使用听力单元原音另行自测。</p><div class="button-row" style="margin:0">${p.listeningScripts.map((s,i)=>`<button class="secondary small" data-speak="${i}">▶ 新闻 ${i+1}</button>`).join('')}<button class="quiet" id="stop-speak">停止朗读</button></div>${m.submitted?`<details><summary>展开听力原稿</summary>${p.listeningScripts.map(s=>`<div class="example">${esc(s.text)}</div>`).join('')}</details>`:''}</div>`:''}${p.sections.map(s=>`<section class="panel space-top"><h2>${esc(s.title)}</h2><p class="hint">${esc(s.instruction||'按要求完成以下题目。')}</p>${s.questions.map((q,i)=>`<div class="mock-question"><span class="question-type">${i+1}. ${q.points!=null?`${q.points} 分`:''}</span>${q.type==='listening'?`<div class="mock-listening-passage">${mockListeningInputs(q,m)}</div>`:`<label for="mockq-${esc(q.id)}">${esc(q.prompt)}</label>`}${q.type==='listening'?'':`<textarea id="mockq-${esc(q.id)}" data-mockanswer="${esc(q.id)}" rows="${q.type==='essay'?9:3}" aria-label="${esc(s.title)}第 ${i+1} 题">${esc(m.answers[q.id]||'')}</textarea><div class="subtle" data-wordcount="${esc(q.id)}">${wordCount(m.answers[q.id]||'')} words</div>`}${m.submitted?`<div class="feedback"><strong>${q.type==='listening'?mockListeningScore(q,m):'参考答案 / 评分提示'}</strong><p>${esc(q.answer)}</p>${esc(q.explanation||'主观题存在合理的不同表达，请按评分要点自评。')}<div class="button-row"><button class="quiet" data-mockmistake="${esc(q.id)}">加入错题本</button></div></div>`:''}</div>`).join('')}</section>`).join('')}${m.submitted?`<section class="panel space-top"><h2>评分与复盘</h2><div class="hint">${esc(typeof p.rubric==='string'?p.rubric:JSON.stringify(p.rubric||'按各题参考答案与评分点自评。'))}</div><p class="hint">本工作台不自动评价作文质量，也不把参考表达当作唯一答案。可复制你的作答交给教师逐题批改。</p><button class="secondary" id="export-mock">导出本卷作答</button></section>`:''}`;$('#mock-back').onclick=()=>{clearInterval(examInterval);window.speechSynthesis?.cancel();mockId='';mocks()};$$('[data-mockanswer]').forEach(e=>{e.readOnly=m.submitted;e.oninput=()=>{m.answers[e.dataset.mockanswer]=e.value;persist();const count=$$('[data-wordcount]').find(c=>c.dataset.wordcount===e.dataset.mockanswer);if(count)count.textContent=wordCount(e.value)+' words'}});const clock=()=>{if(!m.started||m.submitted||!$('#exam-timer')){clearInterval(examInterval);return;}const rem=Math.max(0,(p.duration||100)*60-Math.floor((Date.now()-m.started)/1000));$('#exam-timer').textContent=`${Math.floor(rem/60).toString().padStart(2,'0')}:${(rem%60).toString().padStart(2,'0')}`;$('#exam-timer').classList.toggle('timer-done',rem===0)};if(m.started&&!m.submitted){clock();examInterval=setInterval(clock,1000)}if($('#start-mock'))$('#start-mock').onclick=()=>{m.started=Date.now();persist(true);mockView()};$('#submit-mock').onclick=()=>{if(m.submitted){if(!confirm('重新练习会清空本卷作答，是否继续？'))return;S.mock[p.id]={answers:{},started:null,submitted:false}}else{m.submitted=true;m.finished=Date.now()}window.speechSynthesis?.cancel();persist(true);clearInterval(examInterval);mockView();toast(m.submitted?'已保存作答并展示参考':'已重置本卷')};$$('[data-speak]').forEach(b=>b.onclick=()=>{if(!('speechSynthesis'in window)){toast('当前浏览器不支持设备朗读，请使用听力单元原音');return}speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(p.listeningScripts[+b.dataset.speak].text);utter.lang='en-US';utter.rate=.86;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)utter.voice=voice;utter.onerror=()=>toast('设备朗读未能完成，请使用原音或请他人朗读');speechSynthesis.speak(utter)});if($('#stop-speak'))$('#stop-speak').onclick=()=>window.speechSynthesis?.cancel();$$('[data-mockmistake]').forEach(b=>b.onclick=()=>{const q=p.sections.flatMap(s=>s.questions).find(q=>q.id===b.dataset.mockmistake);S.mistakes[`mock-${p.id}-${q.id}`]={id:`mock-${p.id}-${q.id}`,type:'mock',prompt:q.prompt,answer:q.answer,yourAnswer:q.type==='listening'?mockListeningAnswers(q,m):m.answers[q.id],explanation:q.explanation,date:TODAY()};persist(true);toast('已加入错题本')});if($('#export-mock'))$('#export-mock').onclick=()=>download(`模拟卷${p.id}_我的作答.md`,`# ${p.title}\n\n`+p.sections.map(s=>`## ${s.title}\n\n`+s.questions.map(q=>`${q.prompt}\n\n我的答案：${(q.type==='listening'?mockListeningAnswers(q,m):m.answers[q.id])||'未作答'}\n\n`).join('')).join('\n'),'text/markdown')}
function mistakes(){const items=Object.values(S.mistakes),book=bookReviews();$('#main').innerHTML=heading('LEARN FROM THE GAPS','错过的，值得再练一次。','教材待复习关卡与听力错空，都从这里继续。')+(!items.length&&!book.length?'<div class="panel empty"><h3>暂时没有待复习记录。</h3><p>教材客观题答错，或原题自评为「还需复习」，都会出现在这里。</p><button class="primary" data-go="writing">开始教材闯关</button></div>':'')+(book.length?`<section class="panel"><div class="section-head"><h2>教材原题 · 待复习</h2><span class="tag">${book.length} 组</span></div><p class="hint">保留上次作答和核对结果；进入原关卡后可选择重练。</p>${book.map(({course,mission:m,result:r})=>`<section class="exercise"><span class="question-type">${esc(D.lessons.find(l=>l.id===course.id)?.title||course.id)}</span><h3>${esc(m.title)}</h3><p class="hint">${r.automaticTotal?`客观小题 ${r.automaticScore||0} / ${r.automaticTotal} · `:''}${r.selfAssessed?'含对照自评 · ':''}待复习</p><button class="secondary small" data-review-course="${esc(course.id)}" data-review-mission="${esc(m.id)}">回到这组原题 →</button></section>`).join('')}</section>`:'')+(items.length?`<div class="panel space-top"><h2>听力与辅助练习</h2>${items.map(q=>`<section class="exercise"><h3>${esc(q.prompt)}</h3><p class="hint">上次作答：${esc(q.yourAnswer||'未填写')}</p><details><summary>查看答案与解析</summary><div class="feedback"><strong>${esc(q.answer)}</strong><p>${esc(q.explanation)}</p></div></details><div class="button-row">${q.unit?`<button class="secondary small" data-relisten="${q.unit}" data-question="${esc(q.id)}">回到 Unit ${q.unit} 精听</button>`:''}<button class="quiet" data-resolved="${esc(q.id)}">已掌握，移出错题本 ✓</button></div></section>`).join('')}</div>`:'');$$('[data-review-course]').forEach(b=>b.onclick=()=>{lessonId=b.dataset.reviewCourse;reviewMission={courseId:lessonId,missionId:b.dataset.reviewMission};navigate('writing')});$$('[data-relisten]').forEach(b=>b.onclick=()=>{unitId=+b.dataset.relisten;const u=currentUnit(),index=u.passages.findIndex(p=>p.questions.some(q=>q.id===b.dataset.question));S.drafts['listen:'+u.id+':mode']='practice';S.drafts['listen:'+u.id+':position']=String(Math.max(0,index));persist();navigate('listening')});$$('[data-resolved]').forEach(b=>b.onclick=()=>{delete S.mistakes[b.dataset.resolved];persist(true);mistakes()})}
function library(){const groups=[...new Set(D.files.map(f=>f.group||'其他资料'))];$('#main').innerHTML=heading('YOUR COURSE LIBRARY','你的资料，放在同一张桌上。','讲义可在线阅读，Markdown / CSV 可下载带走。原始文件保持不变。')+`<div class="toolbar"><input id="file-search" class="search" placeholder="搜索资料名称…" aria-label="搜索资料"><button class="secondary small" data-go="mistakes">错题本 (${Object.keys(S.mistakes).length})</button></div><div id="file-results"></div>`;const list=()=>{const q=$('#file-search').value.toLowerCase();$('#file-results').innerHTML=groups.map(g=>{const fs=D.files.filter(f=>(f.group||'其他资料')===g&&f.title.toLowerCase().includes(q));if(!fs.length)return'';return `<section class="panel space-top"><h2>${esc(g)}</h2>${fs.map(f=>`<div class="file-row"><span class="file-icon">${f.path.endsWith('.csv')?'CSV':'MD'}</span><div class="file-name"><strong>${esc(f.title)}</strong><small>${esc(f.description||'备考资料 · 可离线保存')}</small></div>${f.path.endsWith('.md')?`<button class="quiet" data-read="${esc(f.path)}" data-title="${esc(f.title)}">阅读</button>`:''}<a class="quiet" href="${esc(f.path)}" download>下载 ↓</a></div>`).join('')}</section>`}).join('')||'<div class="empty">没有找到匹配资料。</div>';$$('[data-read]').forEach(b=>b.onclick=()=>readFile(b.dataset.read,b.dataset.title))};$('#file-search').oninput=list;list()}
async function readFile(path,title){$('#reader-title').textContent=title;$('#reader-body').textContent='正在打开…';$('#reader').showModal();try{const response=await fetch(path);if(!response.ok)throw Error(response.status);$('#reader-body').innerHTML=markdown(await response.text())}catch{$('#reader-body').textContent='资料暂时无法打开。请检查网络，或从资料库下载原文件。'}}
function openMatching(text,direct=false){const f=D.files.find(f=>f.title.includes(text)||f.path.includes(text));if(!f){toast('请到资料库选择对应讲义');return}if(direct){const a=document.createElement('a');a.href=f.path;a.download='';a.click()}else readFile(f.path,f.title)}
function markdown(input){const inline=t=>esc(t).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');let lines=input.split('\n'),out='',list=false,table=false,code=false;for(let i=0;i<lines.length;i++){let line=lines[i].trimEnd();if(line.startsWith('```')){if(list){out+='</ul>';list=false}out+=code?'</code></pre>':'<pre><code>';code=!code;continue}if(code){out+=esc(line)+'\n';continue}if(line.startsWith('|')&&line.endsWith('|')){if(/^\|[\s:|-]+\|$/.test(line))continue;if(!table){out+='<div class="table-scroll"><table>';table=true}out+='<tr>'+line.slice(1,-1).split('|').map(c=>`<td>${inline(c.trim())}</td>`).join('')+'</tr>';continue}else if(table){out+='</table></div>';table=false}if(/^\s*[-*]\s|^\d+[.)、]\s/.test(line)){if(!list){out+='<ul>';list=true}out+='<li>'+inline(line.replace(/^\s*[-*]\s|^\d+[.)、]\s/,''))+'</li>';continue}if(list){out+='</ul>';list=false}const h=line.match(/^(#{1,6})\s+(.*)/);if(h)out+=`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;else if(line.startsWith('>'))out+='<blockquote>'+inline(line.replace(/^>\s?/,''))+'</blockquote>';else if(/^---+$/.test(line))out+='<hr>';else if(line.trim())out+='<p>'+inline(line)+'</p>'}if(list)out+='</ul>';if(table)out+='</table></div>';if(code)out+='</code></pre>';return out}
function settings(){
  const fx=window.StudyFX?.isEnabled?.()??!matchMedia('(prefers-reduced-motion: reduce)').matches;
  $('#main').innerHTML=heading('TUNE YOUR ORBIT','让学习空间，更像你。','账号、目标与动效，都按自己的节奏设置。')+`<div class="settings-grid"><section class="panel"><div class="card-kicker">ACCOUNT & SYNC</div><h2>${cloudStatus.user?'已连接个人账号':'开启你的个人学习空间'}</h2><p class="hint">${cloudStatus.user?esc(cloudStatus.user.email||''):'登录后，学习进度可在手机与电脑之间接续。游客进度只保存在当前浏览器。'}</p><span class="sync-state" data-state="${esc(cloudStatus.status)}">${esc(cloudStatus.message||'正在检查连接')}</span><div class="button-row"><button class="primary" data-go="account">${cloudStatus.user?'管理账号与同步':'登录 / 注册'} →</button><button class="secondary" data-go="mistakes">我的错题本</button></div></section><section class="panel"><div class="card-kicker">PERSONAL GOAL</div><h2>我的备考目标</h2><div class="field"><label for="name">怎么称呼你</label><input id="name" value="${esc(S.settings.name||'')}" maxlength="30" placeholder="你的名字或昵称"></div><div class="field"><label for="exam-date">考试日期（可选）</label><input type="date" id="exam-date" value="${esc(S.settings.examDate||'')}"></div><div class="field"><label for="plan-select">成长航线</label><select id="plan-select"><option value="14" ${S.plan===14?'selected':''}>14 天标准版</option><option value="7" ${S.plan===7?'selected':''}>7 天精简版</option></select></div><button class="primary" id="save-settings">保存目标</button></section><section class="panel"><div class="card-kicker">ATMOSPHERE</div><h2>沉浸，但不打扰</h2><label class="fx-toggle"><input type="checkbox" id="particles-enabled" ${fx?'checked':''}><span><strong>星空粒子与庆祝动效</strong><small>关闭后画面保持静态，适合专注与省电。</small></span></label><p class="hint">动效会尊重系统“减少动态效果”设置；手机使用较少粒子，切换到后台时暂停。</p><div class="button-row"><button class="secondary small" data-go="library">浏览课程资料</button></div></section><section class="panel"><div class="card-kicker">BACKUP & TRANSFER</div><h2>留一份属于自己的备份</h2><p class="hint">可导出当前账号或游客进度。导入会替换当前可见进度；如果已登录，这些变更也会同步到此账号，请先备份。</p><div class="button-row"><button class="primary" id="export-progress">导出进度</button><button class="secondary" id="import-progress">导入进度</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><p class="hint space-top">退出账号不会删除云端记录。在其他设备重新登录，即可继续学习。</p></section></div>`;
  $('#save-settings').onclick=()=>{S.settings={...S.settings,name:$('#name').value.trim(),examDate:$('#exam-date').value};S.plan=+$('#plan-select').value;S.day=Math.min(S.day,S.plan);persist();toast('备考目标已更新')};$('#particles-enabled').onchange=e=>{window.StudyFX?.setEnabled(e.target.checked);toast(e.target.checked?'星空动效已开启':'已切换为静态专注模式')};$('#export-progress').onclick=()=>download(`拾阶Orbit_进度_${TODAY()}.json`,JSON.stringify({app:'english-studio',exported:new Date().toISOString(),state:S},null,2),'application/json');$('#import-progress').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8e6)throw Error('文件过大');const v=JSON.parse((await file.text()).replace(/^﻿/,''));if(v.app!=='english-studio'||!validState(v.state))throw Error('不是有效的进度文件');if(!confirm(cloudStatus.user?'导入会替换当前账号的学习进度并同步到云端。确定已备份并继续？':'导入会替换当前游客进度，确定已备份并继续？'))return;S={...blankState(),...v.state};persist();settings();toast('备份已导入')}catch(err){toast('无法导入：'+err.message)}};
}
function validState(s){if(!s||typeof s!=='object'||s.version!==1||![7,14].includes(s.plan)||!Number.isInteger(s.day)||s.day<1||s.day>s.plan)return false;for(const k of ['tasks','drafts','results','words','mistakes','read','activity','settings','mock','essays'])if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))return false;if(Object.values(s.results).some(v=>!v||typeof v!=='object'||!Number.isFinite(v.score)||!Number.isFinite(v.total)))return false;if(Object.values(s.words).some(v=>!v||typeof v!=='object'||typeof v.known!=='boolean'))return false;if(Object.values(s.mistakes).some(v=>!v||typeof v!=='object'||typeof v.id!=='string'||typeof v.prompt!=='string'||typeof v.answer!=='string'))return false;if(Object.values(s.mock).some(v=>!v||typeof v!=='object'||!v.answers||typeof v.answers!=='object'||Array.isArray(v.answers)))return false;if(s.settings.name!=null&&typeof s.settings.name!=='string')return false;if(s.settings.examDate!=null&&typeof s.settings.examDate!=='string')return false;if(['prompt','draft'].some(k=>s.essays[k]!=null&&typeof s.essays[k]!=='string'))return false;if(Object.values(s.mock).some(v=>Object.values(v.answers).some(a=>typeof a!=='string')))return false;if(Object.entries(s.drafts).some(([k,v])=>k.startsWith('unit-')?(!v||typeof v!=='object'||Array.isArray(v)||Object.values(v).some(a=>typeof a!=='string')):typeof v!=='string'))return false;return true}
function download(name,text,type){const url=URL.createObjectURL(new Blob(['\ufeff',text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制作文，可粘贴到你选择的批改工具')}catch{download('作文批改请求.txt',text,'text/plain');toast('已下载作文文本')}}
async function boot(){try{const [listening,writing,vocab,mock,files,sentenceBook,coreBooks]=await Promise.all(['listening','writing','vocabulary','mocks','files','textbook-sentence','textbook-core'].map(async name=>{const r=await fetch(`data/${name}.json`);if(!r.ok)throw Error(`${name}: ${r.status}`);return r.json()}));D={units:listening.units||[],lessons:writing.lessons||[],words:vocab.words||[],papers:mock.papers||[],files:files.files||[],courses:[...(sentenceBook.courses||[]),...(coreBooks.courses||[])]};window.StudyCloud.onStatus(onCloudStatus);await window.StudyCloud.init({getState:()=>S,applyState:receiveCloudState,blankState,validateState:validState});render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{})}catch(e){$('#main').innerHTML=`<div class="error-box"><h2>学习资料暂未加载成功</h2><p>请确认通过工作台网址打开，而非双击 HTML 文件，并检查网络连接。</p><button class="primary" id="reload">重新加载</button><p class="hint">${esc(e.message)}</p></div>`;$('#reload').onclick=()=>location.reload()}}
boot();
